local PigFarmer = {}
local PRODUCTS = {
    bacon_pig = { name = "Slaninasta svinja", pigCost = 1, fodderCost = 1, waterCost = 1, time = 3, cost = 25, yield = 40, happiness = 1, description = "Slaninasta svinja za slanino." },
    lard_pig = { name = "Mastna svinja", pigCost = 1, fodderCost = 2, waterCost = 1, time = 4, cost = 35, yield = 50, prestige = 1, description = "Mastna svinja za mast." },
    suckling_pig = { name = "Sesna prašič", pigCost = 1, fodderCost = 1, waterCost = 1, time = 5, cost = 55, yield = 60, prestige = 2, happiness = 1, description = "Sesna prašič za pečenje." },
    silver_tusk_pig = { name = "Srebrnokljuna svinja", pigCost = 1, silverCost = 1, fodderCost = 1, waterCost = 1, time = 8, cost = 160, yield = 80, prestige = 6, happiness = 2, description = "Srebrnokljuna svinja za plemiče." },
    silver_bell_swine = { name = "Srebrno zvončni svinja", pigCost = 2, silverCost = 1, fodderCost = 2, waterCost = 1, time = 11, cost = 400, yield = 90, prestige = 12, happiness = 3, description = "Svinja s srebrnim zvonom za visoke plemiče." },
    royal_grand_swine = { name = "Kraljevski veliki svinja", pigCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, fodderCost = 4, waterCost = 2, time = 16, cost = 1500, yield = 100, prestige = 35, happiness = 8, description = "Velika kraljevska svinja z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Svinjarska postaja", cost = { gold = 200, wood = 120, stone = 200 }, upkeep = 5, qualityBonus = 5 },
    pig_sty = { name = "Svinjak", cost = { gold = 750, wood = 220, stone = 300, fodder = 10 }, upkeep = 18, qualityBonus = 18 },
    smoke_curing_barn = { name = "Kadilno-solilna staja", cost = { gold = 2000, wood = 350, stone = 600, silver = 25, iron = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_pig_atelier = { name = "Kraljevski atelje svinj", cost = { gold = 8000, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 160, qualityBonus = 55, prestigeBonus = 40 },
}
PigFarmer.pigStock = 22; PigFarmer.fodderStock = 24; PigFarmer.waterStock = 18; PigFarmer.silverStock = 8; PigFarmer.goldStock = 6; PigFarmer.jewelStock = 6
PigFarmer.productStock = {}; PigFarmer.buildings = {}; PigFarmer.maker = nil; PigFarmer.activeMaking = {}; PigFarmer.totalProducts = 0; PigFarmer.dayTimer = 0
function PigFarmer.init() PigFarmer.pigStock=22; PigFarmer.fodderStock=24; PigFarmer.waterStock=18; PigFarmer.silverStock=8; PigFarmer.goldStock=6; PigFarmer.jewelStock=6; PigFarmer.productStock={}; PigFarmer.buildings={}; PigFarmer.maker=nil; PigFarmer.activeMaking={}; PigFarmer.totalProducts=0; PigFarmer.dayTimer=0; print("[PigFarmer] Royal Pig Farmer System initialized (6 products, 4 buildings)") end
function PigFarmer.hireMaker(n,s) s=s or math.random(45,85); local c=440+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PigFarmer.maker={name=n or ("Svinjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svinjar najet: %s (spretnost: %d)",PigFarmer.maker.name,s),"success") end; return true end
function PigFarmer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PigFarmer.build(id) local ok,e=PigFarmer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PigFarmer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PigFarmer.getQualityBonus() local b=0; for _,bd in ipairs(PigFarmer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PigFarmer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.pigCost and PigFarmer.pigStock<(d.pigCost or 0) then return false,"Premalo svinj" end; if d.fodderCost and PigFarmer.fodderStock<(d.fodderCost or 0) then return false,"Premalo krme" end; if d.waterCost and PigFarmer.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and PigFarmer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PigFarmer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PigFarmer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #PigFarmer.buildings==0 then return false,"Potrebna delavnica" end; if not PigFarmer.maker then return false,"Potreben svinjar" end; return true end
function PigFarmer.make(pt,qty) qty=qty or 5; local ok,e=PigFarmer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.pigCost then PigFarmer.pigStock=PigFarmer.pigStock-d.pigCost*qty end; if d.fodderCost then PigFarmer.fodderStock=PigFarmer.fodderStock-d.fodderCost*qty end; if d.waterCost then PigFarmer.waterStock=PigFarmer.waterStock-d.waterCost*qty end; if d.silverCost then PigFarmer.silverStock=PigFarmer.silverStock-d.silverCost*qty end; if d.goldCost then PigFarmer.goldStock=PigFarmer.goldStock-d.goldCost*qty end; if d.jewelCost then PigFarmer.jewelStock=PigFarmer.jewelStock-d.jewelCost*qty end; local t=d.time; if PigFarmer.maker then t=math.max(1,t-math.floor(PigFarmer.maker.skill/12)) end; table.insert(PigFarmer.activeMaking,{id="pig_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PigFarmer.completeMaking(m) local q=1.0+(PigFarmer.getQualityBonus()/100); if PigFarmer.maker then q=q+(PigFarmer.maker.skill/180) end; q=math.min(2.0,q); PigFarmer.productStock[m.productType]=(PigFarmer.productStock[m.productType] or 0)+m.quantity; PigFarmer.totalProducts=PigFarmer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PigFarmer.maker then PigFarmer.maker.itemsMade=PigFarmer.maker.itemsMade+m.quantity; if math.random()<0.20 then PigFarmer.maker.skill=math.min(100,PigFarmer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svinja vzrejena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pig.completed",{productName=m.productName,yield=m.yield,happiness=m.happiness}) end end
function PigFarmer.update(dt) if not _G.state then return end; PigFarmer.dayTimer=PigFarmer.dayTimer+dt; if PigFarmer.dayTimer>=30 then PigFarmer.dayTimer=0; for i=#PigFarmer.activeMaking,1,-1 do local m=PigFarmer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PigFarmer.completeMaking(m); table.remove(PigFarmer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PigFarmer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PigFarmer.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PigFarmer.getStats() return {pigStock=PigFarmer.pigStock,fodderStock=PigFarmer.fodderStock,waterStock=PigFarmer.waterStock,silverStock=PigFarmer.silverStock,goldStock=PigFarmer.goldStock,jewelStock=PigFarmer.jewelStock,productStock=PigFarmer.productStock,numBuildings=#PigFarmer.buildings,hasMaker=PigFarmer.maker~=nil,makerName=PigFarmer.maker and PigFarmer.maker.name or "—",makerSkill=PigFarmer.maker and PigFarmer.maker.skill or 0,activeMaking=#PigFarmer.activeMaking,totalProducts=PigFarmer.totalProducts} end
return PigFarmer
